// A. A+B Again?
// 题意：给一个两位数 n，求它的两个数位之和。
// 解法：十位 = n / 10，个位 = n % 10，直接相加。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);           // 关同步，加快 cin / cout
    cin.tie(nullptr);                      // 解除 cin 与 cout 的绑定

    int t;                                 // 测试组数
    cin >> t;
    while (t--) {
        int n;                             // 本组的两位数 n
        cin >> n;
        cout << n / 10 + n % 10 << "\n";    // 十位数字 + 个位数字
    }
    return 0;
}
```

### 易错点

输入的两位数是一整个整数。

